import javax.swing.*;import java.awt.*;import java.sql.SQLException;
public class AttendanceSettingsPanel extends JPanel {
    private final AttendanceSettingsDAO dao=new AttendanceSettingsDAO();private AttendanceSettings settings;private JTextField weekOff,holidays,cl,el,otRate,threshold,bonus,late;private JCheckBox bonusEnabled,bonusPercent;private JLabel bonusHelper;
    public AttendanceSettingsPanel(){setLayout(new GridBagLayout());GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(7,7,7,7);c.fill=GridBagConstraints.HORIZONTAL;settings=dao.load();weekOff=f(settings.weeklyOffDays);holidays=f(settings.publicHolidays);cl=f(settings.casualLeaveLimit);el=f(settings.earnedLeaveLimit);otRate=f(settings.overtimeRatePerHour);threshold=f(settings.attendanceThresholdPercent);bonus=f(settings.bonusIsPercentage?settings.attendanceBonusPercent:settings.attendanceBonusAmount);late=f(settings.lateArrivalGraceMinutes);bonusEnabled=new JCheckBox("Enable attendance bonus",settings.attendanceBonusEnabled);bonusPercent=new JCheckBox("% of Basic Pay",settings.bonusIsPercentage);bonusHelper=new JLabel();bonusPercent.addActionListener(e->helper());int row=0;row=row(c,row,"Weekly off days/month",weekOff);row=row(c,row,"Public holidays/month",holidays);row=row(c,row,"Max Casual Leave (CL) allowed/month",cl);row=row(c,row,"Max Earned Leave (EL) allowed/month",el);row=row(c,row,"Overtime rate per hour",otRate);row=row(c,row,"Attendance threshold (%)",threshold);c.gridx=0;c.gridy=row;add(new JLabel("Attendance bonus"),c);c.gridx=1;add(bonus,c);c.gridx=2;add(bonusPercent,c);c.gridx=3;add(bonusHelper,c);helper();row++;row=row(c,row,"Late-arrival grace minutes",late);c.gridx=1;c.gridy=row++;add(bonusEnabled,c);JButton save=new JButton("Save Attendance Rules");save.addActionListener(e->save());c.gridx=1;c.gridy=row;add(save,c);}
    private void helper(){bonusHelper.setText(bonusPercent.isSelected()?"(% of Basic Salary)":"(Fixed Amount)");}
    private JTextField f(Object value){return new JTextField(value instanceof Double||value instanceof Float?Money.text(((Number)value).doubleValue()):String.valueOf(value),12);}private int row(GridBagConstraints c,int row,String label,JTextField field){c.gridx=0;c.gridy=row;add(new JLabel(label),c);c.gridx=1;add(field,c);return row+1;}
    private void save(){try{settings.weeklyOffDays=Integer.parseInt(weekOff.getText());settings.publicHolidays=Integer.parseInt(holidays.getText());settings.casualLeaveLimit=Integer.parseInt(cl.getText());settings.earnedLeaveLimit=Integer.parseInt(el.getText());settings.overtimeRatePerHour=Double.parseDouble(otRate.getText());settings.attendanceThresholdPercent=Double.parseDouble(threshold.getText());settings.attendanceBonusEnabled=bonusEnabled.isSelected();settings.bonusIsPercentage=bonusPercent.isSelected();if(settings.bonusIsPercentage)settings.attendanceBonusPercent=Double.parseDouble(bonus.getText());else settings.attendanceBonusAmount=Double.parseDouble(bonus.getText());settings.lateArrivalGraceMinutes=Integer.parseInt(late.getText());dao.save(settings);for(Employee employee:new EmployeeDAO().list("")){CTCStore.Value value=CTCStore.get(employee.getId());value.attendance=settings.attendanceBonusEnabled?(settings.bonusIsPercentage?settings.attendanceBonusPercent*employee.getBasicSalary()/100:settings.attendanceBonusAmount):0;}JOptionPane.showMessageDialog(this,"Attendance rules saved.");}catch(NumberFormatException|SQLException e){JOptionPane.showMessageDialog(this,"Enter valid numeric settings.");}}
}
